/// <reference types="@workadventure/iframe-api-typings" />
import { bootstrapExtra } from "@workadventure/scripting-api-extra";

console.info("[QuantX] map script started");

let popup: any = undefined;
function closePopup() {
    if (popup !== undefined) { popup.close(); popup = undefined; }
}
function show(anchor: string, msg: string) {
    closePopup();
    popup = WA.ui.openPopup(anchor, msg, [{ label: "OK", className: "primary", callback: () => closePopup() }]);
}
function onArea(area: string, anchor: string, msg: string) {
    WA.room.area.onEnter(area).subscribe(() => show(anchor, msg));
    WA.room.area.onLeave(area).subscribe(closePopup);
}

const DIRECTORY =
    "DIRECTORY - Quant X Club\n\n" +
    "↖ LECTURE HALL (north-west): weekly lecture. Go through the door marked ▲ LECTURE.\n" +
    "↗ BREAKOUT ROOMS 1-3 (north-east): cross the Arena and use the doors marked ▲ ROOM 1/2/3.\n" +
    "↘ ARENA (south-east, grass): coming soon.\n" +
    "● You are in the LOBBY (south-west).";

const HOWTO =
    "How to get around:\n" +
    "• Move: arrow keys or W A S D (or click a spot)\n" +
    "• Walk next to people to start a video/voice chat\n" +
    "• In the Lecture Hall or a Breakout Room, press SPACE to join its video call\n" +
    "• Signposts show directions. Click 'Map guide' (top bar) any time.";

function openGuide() {
    const url = new URL("guide.html", WA.room.mapURL).toString();
    try {
        WA.ui.modal.openModal({ title: "Map guide", src: url, allow: null, allowApi: false, position: "center" } as any);
    } catch (e) {
        console.error(e);
        WA.nav.openCoWebSite(url);
    }
}

WA.onInit().then(() => {
    console.info("[QuantX] Scripting API ready");
    const name = WA.player.name || "trader";

    show("welcomePopup", `Welcome to Quant X Club, ${name}!\n\n` + HOWTO + "\n\nThe DIRECTORY board just south of you lists every room.");
    WA.room.area.onLeave("lobby").subscribe(closePopup);

    onArea("directorySign", "directoryPopup", DIRECTORY);
    onArea("postLobby", "postLobbyPopup", "↑ LECTURE HALL: door just north-east of here (▲ LECTURE)\n↘ ARENA and BREAKOUT ROOMS: head south-east through the gap in the wall");
    onArea("postGap", "postGapPopup", "→ ARENA: through the gap just east of here\n↗ BREAKOUT ROOMS 1-3: cross the Arena and go north\n↖ LECTURE HALL: back north-west");
    onArea("postArena", "postArenaPopup", "↑ BREAKOUT ROOMS: doors ▲ ROOM 1 (left), ROOM 2 (right of here), ROOM 3 (far right)\n← LOBBY & LECTURE HALL: go west through the gap at the bottom-left");
    onArea("arenaSign", "arenaPopup", "ARENA - coming soon!\nTrading battles and quiz duels will happen here. (placeholder)");
    onArea("stage", "stagePopup", "You are on the STAGE. Lecturers: present from here and share your screen in the Lecture Hall call.");

    for (const r of ["breakout1", "breakout2", "breakout3"]) {
        WA.room.area.onEnter(r).subscribe(() =>
            WA.ui.displayActionMessage({ message: `${r.replace("breakout", "Breakout Room ")}: press SPACE to join the group call`, callback: () => {}, type: "message" }));
    }

    // Persistent "Map guide" button in the action bar
    try {
        WA.ui.actionBar.addButton({ id: "qxc-map-guide", label: "Map guide", callback: () => openGuide() } as any);
    } catch (e) { console.error("[QuantX] could not add action bar button", e); }

    bootstrapExtra().then(() => console.info("[QuantX] Scripting API Extra ready")).catch(e => console.error(e));
}).catch(e => console.error(e));

export {};
